document.addEventListener("DOMContentLoaded", () => {
    let inactivityTimer;
    let isUserInteracting = false;
    const INACTIVITY_DELAY = 1000; // Resume autoplay after 2 seconds
    const AUTOPLAY_DELAY = 0; // 0 seconds between slides

    var swiper = new Swiper(".gallery_slider", {
      slidesPerView: "auto",
      spaceBetween: 20,
      freeMode: true,
      autoplay: {
        delay: AUTOPLAY_DELAY,
        disableOnInteraction: false,
        pauseOnMouseEnter: true,
      },
      speed: 8000,
      navigation: {
        nextEl: ".swiper-freemode_button-next",
        prevEl: ".swiper-freemode_button-prev",
      },
      pagination: {
        el: ".swiper-freemode_pagination",
        clickable: true,
      },
      on: {
        touchStart: function () {
          isUserInteracting = true;
          swiper.autoplay.stop();
          clearTimeout(inactivityTimer);
        },
        touchEnd: function () {
          resetInactivityTimer();
        },
        slideChange: function () {
          if (isUserInteracting) {
            resetInactivityTimer();
          }
        },
      },
    });

    // Track navigation clicks
    const nextBtn = document.querySelector(".swiper-freemode_button-next");
    const prevBtn = document.querySelector(".swiper-freemode_button-prev");
    const pagination = document.querySelector(".swiper-freemode_pagination");

    [nextBtn, prevBtn, pagination].forEach((el) => {
      if (el) {
        el.addEventListener("click", () => {
          isUserInteracting = true;
          swiper.autoplay.stop();
          resetInactivityTimer();
        });
      }
    });

    // Track mouse events
    const slider = document.querySelector(".gallery_slider");
    if (slider) {
      slider.addEventListener("mouseenter", () => {
        isUserInteracting = true;
        swiper.autoplay.stop();
        clearTimeout(inactivityTimer);
      });

      slider.addEventListener("mouseleave", () => {
        resetInactivityTimer();
      });

      slider.addEventListener("wheel", () => {
        isUserInteracting = true;
        swiper.autoplay.stop();
        resetInactivityTimer();
      });
    }

    function resetInactivityTimer() {
      clearTimeout(inactivityTimer);
      inactivityTimer = setTimeout(() => {
        isUserInteracting = false;
        swiper.autoplay.start();
      }, INACTIVITY_DELAY);
    }

    resetInactivityTimer();
  });

$(document).ready(function () {
    $('#skip').on('click keydown', function(e) {
      if (e.type === "keydown" && e.which !== 13) {
          return;
      }

      e.preventDefault();
      var target = $('#main');
      target.attr('tabindex', '-1');
      target.focus();
    });
  });

function initDynamicCurrentYear() {  
  const currentYear = new Date().getFullYear();
  const currentYearElements = document.querySelectorAll('[data-current-year]');
  currentYearElements.forEach(currentYearElement => {
    currentYearElement.textContent = currentYear;
  });
}

// Initialize Dynamic Current Year
document.addEventListener('DOMContentLoaded', () => {
  initDynamicCurrentYear();
});
